static unsigned long checks,failed;
#define CHECK(x,m) do{++checks;if(!(x)){++failed;printf("FAIL remote-position %s line%d\n",m,__LINE__);}}while(0)
typedef struct Fixture {BHEntityPool pool;BHEntity *e,*local,*remote[8];BHWorldGeometry worlds[2];BHPickupRoom rooms[2];BHNavigation navigation;BHNavigationNode nodes[2];BHRemotePackets packets;unsigned long tick;long slot;unsigned char bytes[64];unsigned long wire;}Fixture;
static unsigned long word(BHEntity *e,unsigned long o){unsigned long n;memcpy(&n,(char*)e+o,4);return n;}
static void field(BHEntity *e,unsigned long o,unsigned long n){memcpy((char*)e+o,&n,4);}
static unsigned short half(BHEntity *e,unsigned long o){unsigned short n;memcpy(&n,(char*)e+o,2);return n;}
static void sethalf(BHEntity *e,unsigned long o,unsigned short n){memcpy((char*)e+o,&n,2);}
static float number(BHEntity *e,unsigned long o){float f;memcpy(&f,(char*)e+o,4);return f;}
static void real(BHEntity *e,unsigned long o,float f){memcpy((char*)e+o,&f,4);}
static int setup(Fixture *f){unsigned long i;memset(f,0,sizeof(*f));if(!bh_entities_init(&f->pool,4,0))return 0;f->e=bh_entity_acquire(&f->pool);f->local=bh_entity_acquire(&f->pool);if(!f->e||!f->local)return 0;f->remote[0]=f->e;f->slot=1;f->tick=40;for(i=0;i<2;++i){f->worlds[i].maximum.x=f->worlds[i].maximum.y=f->worlds[i].maximum.z=32768;f->worlds[i].navigation.next=&f->worlds[1-i].navigation;f->worlds[i].previous=f->worlds+1-i;f->rooms[i].world=f->worlds+i;f->nodes[i].placement=f->worlds+i;}f->navigation.nodes=f->nodes;f->navigation.node_count=2;f->rooms[0].actors=f->e;field(f->e,0x198,(unsigned long)f->worlds);for(i=0;i<3;++i){sethalf(f->e,0x13c+32*i,(unsigned short)(10*(i+1)));real(f->e,0x140+32*i,(float)(10*(i+1)));field(f->e,0x158+32*i,(unsigned long)f->worlds);}f->packets.pool=&f->pool;f->packets.remote=f->remote;f->packets.local_slot=&f->slot;f->packets.simulation_tick=&f->tick;f->packets.local=f->local;f->packets.rooms=f->rooms;f->packets.room_count=2;f->packets.navigation=&f->navigation;return 1;}
static int packet(Fixture *f,unsigned short tick,unsigned short slot,unsigned short world,float x,signed char yaw,signed char pitch,signed char roll,unsigned char flags){BHPacketWriter w;BHVec3 point;unsigned char angles[4];point.x=x;point.y=point.z=0;memcpy(angles,&yaw,1);memcpy(angles+1,&pitch,1);memcpy(angles+2,&roll,1);angles[3]=flags;return bh_packet_begin(&w,f->bytes,64,4,tick)&&bh_packet_append(&w,&slot,2)&&bh_packet_write_position(&w,f->worlds+(world<2?world:0),world,&point)&&bh_packet_append(&w,angles,4)&&bh_packet_finish(&w,&f->wire);}
static int receive(Fixture *f){return bh_remote_position_packet(&f->packets,f->bytes,f->wire,64);}
static void finish(Fixture *f){CHECK(bh_entities_dispose(&f->pool),"actual source pool lifecycle");}
int bh_remote_position_checkpoint(unsigned long *count){Fixture f;BHMathEnvironment env;unsigned long i,processed;BHPacketWriter writer;unsigned short slot;double old_angle,new_angle,difference,expected;float quant=.02454369328916073f;
 checks=failed=0;CHECK(bh_math_environment_enter(&env),"PC53");CHECK(setup(&f),"actual source entity/navigation/room owners");CHECK(packet(&f,40,0,0,40,0,0,0,6)&&receive(&f),"whole newest snapshot");CHECK(half(f.e,0x13c)==20&&half(f.e,0x15c)==30&&half(f.e,0x17c)==40&&number(f.e,0x140)==20&&number(f.e,0x160)==30&&number(f.e,0x180)==40,"three actual32-byte bank shift");CHECK(number(f.e,0x48)==.5f&&number(f.e,0x60)==0&&half(f.e,0x11a)==6&&f.packets.processed==1&&!f.packets.pending,"independent linear slope/smoothing/flags");
 CHECK(packet(&f,30,0,0,35,0,0,0,0)&&receive(&f)&&number(f.e,0x160)==35&&half(f.e,0x13c)==20,"equal-middle timestamp updates without shifting");CHECK(fabs(number(f.e,0x48)-.5)<.000001&&fabs(number(f.e,0x60)+.05)<.000001,"unequal consecutive slopes produce actual acceleration");CHECK(packet(&f,25,0,0,25,0,0,0,0)&&receive(&f)&&half(f.e,0x13c)==25&&number(f.e,0x140)==25,"oldest interval update");CHECK(fabs(number(f.e,0x60)+.1)<.000001,"independent old slope denominator");CHECK(packet(&f,35,0,0,35,0,0,0,0)&&receive(&f)&&half(f.e,0x13c)==30&&half(f.e,0x15c)==35&&half(f.e,0x17c)==40,"intermediate arrival copies middle to oldest");CHECK(fabs(number(f.e,0x48)-.75)<.000001&&fabs(number(f.e,0x60)-.05)<.000001,"new intermediate derivatives");CHECK(packet(&f,40,0,0,45,0,0,0,0)&&receive(&f)&&number(f.e,0x180)==45&&half(f.e,0x15c)==35,"equal-newest update");CHECK(fabs(number(f.e,0x48)-1.375)<.000001&&fabs(number(f.e,0x60)-.225)<.000001,"equal-newest smoothing");processed=f.packets.processed;CHECK(packet(&f,20,0,0,1,0,0,0,0)&&receive(&f)&&f.packets.pending==2&&f.packets.processed==processed&&f.packets.reader.cursor==10,"too-old packet retains original extra pending increment");finish(&f);
 CHECK(setup(&f),"clamp/age fixture");for(i=0;i<3;++i)real(f.e,0x140+32*i,0);f.tick=45;CHECK(packet(&f,40,0,0,1000,0,0,0,0)&&receive(&f),"large slope with age decay");CHECK(fabs(number(f.e,0x48)-10*pow(.965,5))<.000002&&fabs(number(f.e,0x60)-2*pow(.8,5))<.000002,"independent10/2 clamps then original pow factors");finish(&f);
 CHECK(setup(&f),"angular boundary fixture");real(f.e,0x18c,(float)(120*(double)quant));real(f.e,0x190,(float)(-120*(double)quant));real(f.e,0x194,(float)(-64*(double)quant));CHECK(packet(&f,40,0,0,40,-120,120,64,0)&&receive(&f),"signed byte angular samples");for(i=0;i<3;++i){old_angle=(float)((i==0?120:i==1?-120:-64)*(double)quant);new_angle=(float)((i==0?-120:i==1?120:64)*(double)quant);difference=(float)(new_angle-old_angle);expected=atan2(sin(difference),cos(difference))/20;CHECK(fabs(number(f.e,0x54+4*i)-expected)<.000001,"independent atan2 direction verifies fmod wrap across both pi signs");}finish(&f);
 CHECK(setup(&f),"room movement fixture");f.rooms[1].actors=f.local;field(f.local,0x198,(unsigned long)(f.worlds+1));CHECK(packet(&f,40,0,1,40,0,0,0,0)&&receive(&f)&&!f.rooms[0].actors&&f.rooms[1].actors==f.e&&word(f.e,0xf4)==(unsigned long)f.local&&word(f.local,0xf8)==(unsigned long)f.e&&word(f.e,0x198)==(unsigned long)(f.worlds+1),"actual reciprocal room unlink/insertion follows decoded world");finish(&f);
 CHECK(setup(&f),"modular timestamp fixture");for(i=0;i<3;++i){sethalf(f.e,0x13c+32*i,(unsigned short)(65534+i));real(f.e,0x140+32*i,(float)i);}f.tick=1;CHECK(packet(&f,1,0,0,3,0,0,0,0)&&receive(&f)&&half(f.e,0x13c)==65535&&half(f.e,0x15c)==0&&half(f.e,0x17c)==1&&number(f.e,0x48)==.5f,"signed16 ordering spans tick wrap");finish(&f);
 CHECK(setup(&f),"equal-stamp fixture");f.tick=100;for(i=0;i<3;++i){sethalf(f.e,0x13c+32*i,100);real(f.e,0x140+32*i,0);}CHECK(packet(&f,100,0,0,10,0,0,0,0)&&receive(&f)&&number(f.e,0x160)==10&&number(f.e,0x48)==-5&&number(f.e,0x60)==-2,"equal stamps replace zero denominators withone then clamp");finish(&f);
 CHECK(setup(&f),"local shared storage fixture");f.rooms[0].actors=f.local;memcpy((char*)f.local+0x13c,(char*)f.e+0x13c,96);field(f.local,0xf4,0);field(f.local,0xf8,0);CHECK(packet(&f,40,1,0,40,0,0,0,0)&&receive(&f)&&number(f.local,0x180)==40&&number(f.e,0x180)==30,"local slot resolves actual local entity");finish(&f);
 CHECK(setup(&f),"malformed packet fixture");CHECK(packet(&f,40,7,0,40,0,0,0,0)&&receive(&f)&&f.packets.pending==1,"missing remote no-op retains pending");CHECK(packet(&f,40,9,0,40,0,0,0,0)&&!receive(&f)&&f.packets.bad==1&&f.packets.pending==1,"invalid actor slot rejected");CHECK(packet(&f,40,0,99,40,0,0,0,0)&&!receive(&f)&&f.packets.bad==2&&f.packets.reader.cursor==12&&half(f.e,0x17c)==40,"actual position decoder rejects index after timestamp effects");CHECK(packet(&f,41,0,0,41,0,0,0,0),"checksum control packet");f.bytes[4]^=1;CHECK(!receive(&f)&&f.packets.bad==3,"real checksum rejection");slot=0;CHECK(bh_packet_begin(&writer,f.bytes,64,4,42)&&bh_packet_append(&writer,&slot,2)&&bh_packet_finish(&writer,&f.wire)&&!receive(&f)&&f.packets.error==3,"truncated position after framing");finish(&f);bh_math_environment_leave(&env);if(count)*count=checks;printf("{\"scenario\":\"remote-position\",\"checks\":%lu,\"failures\":%lu,\"original_code_required\":false}\n",checks,failed);return failed!=0;
}
